using Builder.Core;
using System.Collections.Immutable;
using System.Security.Cryptography;
using System.Text.Json;

internal static class RadialArrayChecks
{
    public static async Task Run(string root,string? evidenceRoot=null)
    {
        var output=evidenceRoot??Path.Combine(root,".local/evidence/radial-array-20261022/core");Directory.CreateDirectory(output);var input=Path.Combine(root,".local/fixtures/distribution/distribution-assembly.3mf");var cases=new List<string>();var outputs=new List<object>();
        void Pass(string name){cases.Add(name);Console.WriteLine("PASS "+name);}
        async Task Save(EditorSession session,string filename,RadialArrayRequest request,string expected)
        {var path=Path.Combine(output,filename);Ok(await session.SaveAsync(path));outputs.Add(new{path=filename,sha256=Hash(path),request,expected});using var reader=new EditorSession();Ok(await reader.OpenAsync(path));Check(reader.Snapshot.Scene.Objects.Length==session.Snapshot.Scene.Objects.Length&&reader.Snapshot.Scene.Groups.Length==session.Snapshot.Scene.Groups.Length,"Native array ownership lost.");Near(reader.Snapshot.Scene.Bounds.Min,session.Snapshot.Scene.Bounds.Min);Near(reader.Snapshot.Scene.Bounds.Max,session.Snapshot.Scene.Bounds.Max);Check(Colors(reader.Snapshot.Scene).SequenceEqual(Colors(session.Snapshot.Scene)),"Native array colors lost.");}
        foreach(var axis in Enum.GetValues<RadialArrayAxis>())foreach(var angle in new[]{90d,-90d})foreach(var rotate in new[]{true,false})
        {
            using var session=new EditorSession();Ok(await session.OpenAsync(input));var left=session.Snapshot.Scene.Objects[0].Id;Ok(session.Execute(new RotateObject(left,new(13,21,9))));var ids=session.Snapshot.Scene.Objects.Take(2).Select(o=>o.Id).ToImmutableArray();Ok(session.SelectMany(ids,ids[1]));var before=session.Snapshot;var pivot=new Vec3(10,-5,3);var request=new RadialArrayRequest(ids,3,angle,axis,pivot,rotate);Ok(await session.PreviewAsync(request));var preview=session.Snapshot.Preview!;
            Check(((ArrangementRequest)preview.Request).ObjectIds.SequenceEqual(ids)&&preview.ResultObjectIds.Length==4&&preview.SelectedObjectIds.SequenceEqual(preview.ResultObjectIds),"Array confused source and copy selection.");Verify(preview.Scene,before.Scene,ids,3,angle,axis,pivot,rotate);
            Check(preview.SelectedObjectId==preview.Scene.Objects[before.Scene.Objects.Length+1].Id,"Primary was not first-placement selected counterpart.");var candidate=preview.Scene;Apply(session);Ok(session.Undo());Check(ReferenceEquals(session.Snapshot.Scene,before.Scene)&&session.Snapshot.SelectedObjectIds.SequenceEqual(before.SelectedObjectIds),"Undo did not restore exact scene/selection.");Ok(session.Redo());Check(ReferenceEquals(session.Snapshot.Scene,candidate),"Redo regenerated IDs.");
        }
        Pass("Positive/negative radial steps around X/Y/Z and explicit pivots rotate whole accepted sets or orbit them with fixed orientation; copy selection, original refs and exact Undo/Redo hold");
        using(var session=new EditorSession())
        {
            Ok(await session.OpenAsync(input));var before=session.Snapshot;var group=before.Scene.Groups.Single();var ids=ImmutableArray.Create(before.Scene.Objects[0].Id,group.ObjectIds[0]);var expanded=before.Scene.Objects.Where(o=>ids.Contains(o.Id)||group.ObjectIds.Contains(o.Id)).Select(o=>o.Id).ToImmutableArray();var request=new RadialArrayRequest(ids,4,90,RadialArrayAxis.Z,new());Ok(await session.PreviewArrangementAsync(request));var preview=session.Snapshot.Preview!;Check(preview.Scene.Groups.Length==4&&preview.ResultObjectIds.Length==12,"Group copies missing.");Verify(preview.Scene,before.Scene,expanded,4,90,RadialArrayAxis.Z,new(),true);
            foreach(var clone in preview.Scene.Groups.Skip(1))Check(clone.Id!=group.Id&&clone.Name==group.Name+" copy"&&clone.ObjectIds.Length==3&&clone.ObjectIds.All(preview.ResultObjectIds.Contains),"Copied group membership invalid.");Apply(session);await Save(session,"group-radial.3mf",request,"Left anchor and Color trio repeat as one set at90/180/270degrees aroundworldZorigin;17leaves4groups, originals unchanged");
        }
        using(var member=new EditorSession())
        {
            Ok(await member.OpenAsync(input));var group=member.Snapshot.Scene.Groups.Single();var id=group.ObjectIds[1];Ok(member.EnterGroup(group.Id,id));Ok(await member.PreviewSurfaceMaterialAsync(new(id,2,new("Face highlight",new(255,210,40)),SurfacePaintMode.Triangle){MemberGroupId=group.Id}));Apply(member);var ids=group.ObjectIds.Take(2).ToImmutableArray();Ok(member.SelectMany(ids,id));var before=member.Snapshot;var request=new RadialArrayRequest(ids,3,-60,RadialArrayAxis.Y,new(12,4,7),false){MemberGroupId=group.Id};
            Check((await member.PreviewArrangementAsync(request with{MemberGroupId=null})).Outcome==Outcome.Conflict,"Radial borrowed member authority.");Same(member,before);Ok(await member.PreviewArrangementAsync(request));var preview=member.Snapshot.Preview!;Verify(preview.Scene,before.Scene,ids,3,-60,RadialArrayAxis.Y,request.PivotMillimeters,false);Check(preview.Scene.Groups.Length==1&&preview.Scene.Groups[0].ObjectIds.SequenceEqual(group.ObjectIds.AddRange(preview.ResultObjectIds)),"Member copies did not append owning group.");Apply(member);Check(member.Snapshot.EditingGroupId==group.Id&&member.Snapshot.SelectedObjectIds.SequenceEqual(preview.ResultObjectIds),"Member scope/copy selection lost.");await Save(member,"member-radial.3mf",request,"Blue and painted Green orbit as a set withoutchangingorientation at−60/−120degrees aroundYline(12,4,7);4newleavesappend originalgroup, Violet/anchors unchanged");Ok(member.Undo());Check(ReferenceEquals(member.Snapshot.Scene,before.Scene),"Member Undo source not exact.");
        }
        Pass("Root groups clone with fresh group/member identities per placement; scoped members append owning group and preserve face materials, context and native roundtrip");
        using(var session=new EditorSession())
        {
            Ok(await session.OpenAsync(input));var id=session.Snapshot.Scene.Objects[0].Id;Ok(session.Execute(new RenameObject(id,"Temporary")));Ok(session.Undo());Ok(session.Select(null));var before=session.Snapshot;var request=new RadialArrayRequest([id],1,0,RadialArrayAxis.Z,new());Ok(await session.PreviewArrangementAsync(request));Check(ReferenceEquals(session.Snapshot.Preview!.Scene,before.Scene)&&session.Snapshot.Preview.SelectedObjectIds.IsEmpty&&session.Snapshot.Preview.SelectedObjectId is null,"Count1 changed scene/selection.");Apply(session);Same(session,before);
            foreach(var bad in new[]{request with{Count=0},request with{Count=2},request with{AngleStepDegrees=double.NaN},request with{AngleStepDegrees=361},request with{Axis=(RadialArrayAxis)99},request with{PivotMillimeters=new(double.NaN,0,0)},request with{PivotMillimeters=new(10_000_001,0,0)},request with{ObjectIds=[Guid.NewGuid()]},request with{ObjectIds=[]},request with{Count=int.MaxValue,AngleStepDegrees=1}})
            {Check((await session.PreviewArrangementAsync(bad)).Outcome==Outcome.Invalid,"Invalid radial settings/budget accepted.");Same(session,before);}
            Ok(await session.PreviewArrangementAsync(request with{Count=3,AngleStepDegrees=360}));var overlap=session.Snapshot.Preview!;Verify(overlap.Scene,before.Scene,[id],3,360,RadialArrayAxis.Z,new(),true);Check(overlap.ResultObjectIds.Length==2,"Full turns incorrectly discarded copies.");Check(session.DiscardPreview(overlap.Id).Outcome==Outcome.Cancelled,"Discard failed.");Same(session,before);
            Ok(session.Execute(new AddPrimitive(PrimitiveKind.Sphere,new(20,20,20))));var sphere=session.Snapshot.SelectedObjectId!.Value;var dense=session.Snapshot;Check((await session.PreviewArrangementAsync(new RadialArrayRequest([sphere],900,1,RadialArrayAxis.Z,new()))).Outcome==Outcome.Invalid,"Expanded triangle/vertex budgets bypassed.");Same(session,dense);
        }
        Pass("Invalid counts/axis/angle/pivot/targets and expanded budgets refuse; Count1 preserves exact empty selection and Redo, while full-turn coincident copies remain intentionally valid");
        using(var session=new EditorSession())
        {
            Ok(await session.OpenAsync(input));var id=session.Snapshot.Scene.Objects[0].Id;Ok(session.Select(id));var before=session.Snapshot;var firstRequest=new RadialArrayRequest([id],2,45,RadialArrayAxis.Z,new());Ok(await session.PreviewArrangementAsync(firstRequest));var first=session.Snapshot.Preview!;var request=firstRequest with{Count=3,AngleStepDegrees=-90,RotateCopies=false};Ok(await session.PreviewArrangementAsync(request,first.Id));var held=session.Snapshot;Check(held.Preview!.Id!=first.Id,"Replacement reused old token.");Verify(held.Preview.Scene,before.Scene,[id],3,-90,RadialArrayAxis.Z,new(),false);
            Check((await session.PreviewArrangementAsync(request,first.Id)).Outcome==Outcome.Conflict,"Old token accepted.");Same(session,held);Check((await session.PreviewArrangementAsync(request,held.Preview.Id,expectedRevision:before.Revision-1)).Outcome==Outcome.Conflict,"Stale revision accepted.");Same(session,held);Check((await session.PreviewArrangementAsync(request with{ObjectIds=[before.Scene.Objects[1].Id]},held.Preview.Id)).Outcome==Outcome.Conflict,"Changed target accepted.");Same(session,held);Check((await session.PreviewArrangementAsync(request with{Count=0},held.Preview.Id)).Outcome==Outcome.Invalid,"Failed replacement accepted.");Same(session,held);
            foreach(var stage in new[]{"Preparing radial array","Creating array copies","Ready to preview"}){using var ct=new CancellationTokenSource();Check((await session.PreviewArrangementAsync(request,held.Preview.Id,ct.Token,new Progress(p=>{if(p.Stage==stage)ct.Cancel();}))).Outcome==Outcome.Cancelled,"Cancellation failed at "+stage);Same(session,held);}
            using(var entered=new ManualResetEventSlim())using(var release=new ManualResetEventSlim())using(var ct=new CancellationTokenSource())
            {var task=session.PreviewArrangementAsync(request,held.Preview.Id,ct.Token,new Progress(p=>{if(p.Stage=="Ready to preview"){entered.Set();Check(release.Wait(10000),"Radial barrier timeout.");}}));Check(entered.Wait(10000),"No radial final barrier.");Check(session.Select(null).Outcome==Outcome.Busy,"Busy selection permitted.");ct.Cancel();release.Set();Check((await task).Outcome==Outcome.Cancelled,"Busy cancel failed.");Same(session,held);}
            var candidate=held.Preview.Scene;Apply(session);Check(session.Snapshot.Revision==before.Revision+1&&session.Snapshot.FilePath==before.FilePath,"Apply history/path wrong.");Ok(session.Undo());Check(ReferenceEquals(session.Snapshot.Scene,before.Scene)&&!session.Snapshot.IsDirty,"Undo lost clean accepted source.");Ok(session.Redo());Check(ReferenceEquals(session.Snapshot.Scene,candidate),"Redo changed copy IDs.");
        }
        Pass("Repreview derives from accepted source and canonical targets; stale/failed/cancelled/busy work retains accepted scene and held candidate, with one native-path-preserving Undo step");
        File.WriteAllText(Path.Combine(output,"radial-array-results.json"),JsonSerializer.Serialize(new{timestamp=DateTimeOffset.UtcNow,scenarioCount=cases.Count,cases,outputs,runtime=System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription,core=new{path=typeof(EditorSession).Assembly.Location,sha256=Hash(typeof(EditorSession).Assembly.Location)},input=new{path=input,sha256=Hash(input)},limitations="Explicit world-axis/pivot array. Copies may overlap, including full turns; no collision packing. Orientation-off uses accepted aggregate bounds center. Scene1000objects/100kfaces/300kvertices/500groups plus native1000mesh+groupresource budgets apply. No UI/native claim."},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"{cases.Count} radial array groups passed. Evidence: {output}");
    }
    private static void Verify(Scene after,Scene before,ImmutableArray<Guid> ids,int count,double step,RadialArrayAxis axis,Vec3 pivot,bool rotate)
    {
        foreach(var obj in before.Objects)Check(ReferenceEquals(after.Objects.Single(o=>o.Id==obj.Id),obj),"Radial changed original.");var originals=before.Objects.Where(o=>ids.Contains(o.Id)).ToArray();var center=Bounds3.From(originals.SelectMany(o=>o.Mesh.Vertices.Select(o.Transform.Apply))).Center;var offset=before.Objects.Length;
        for(var placement=1;placement<count;placement++)foreach(var original in originals)
        {var copy=after.Objects[offset++];Check(copy.Id!=original.Id&&ReferenceEquals(copy.Mesh,original.Mesh)&&ReferenceEquals(copy.Material,original.Material)&&ReferenceEquals(copy.TriangleMaterials,original.TriangleMaterials),"Copy identity/ownership wrong.");var delta=Rotated(center,pivot,axis,placement*step%360)-center;for(var i=0;i<original.Mesh.Vertices.Length;i++){var world=original.Transform.Apply(original.Mesh.Vertices[i]);Near(copy.Transform.Apply(copy.Mesh.Vertices[i]),rotate?Rotated(world,pivot,axis,placement*step%360):world+delta);}if(!rotate)Check(copy.Transform.X==original.Transform.X&&copy.Transform.Y==original.Transform.Y&&copy.Transform.Z==original.Transform.Z,"Fixed-orientation copy rotated.");}
        Check(after.Objects.Length==offset,"Unexpected copy count.");
    }
    private static Vec3 Rotated(Vec3 point,Vec3 pivot,RadialArrayAxis axis,double degrees)
    {var p=point-pivot;var rad=degrees*Math.PI/180;var c=Math.Cos(rad);var s=Math.Sin(rad);return pivot+(axis switch{RadialArrayAxis.X=>new Vec3(p.X,p.Y*c-p.Z*s,p.Y*s+p.Z*c),RadialArrayAxis.Y=>new Vec3(p.X*c+p.Z*s,p.Y,-p.X*s+p.Z*c),_=>new Vec3(p.X*c-p.Y*s,p.X*s+p.Y*c,p.Z)});}
    private static string[] Colors(Scene scene)=>scene.Objects.SelectMany(o=>Enumerable.Range(0,o.Mesh.Triangles.Length).Select(i=>(o.GetTriangleMaterial(i)?.Color??SurfaceMaterial.Neutral.Color).Hex)).Order().ToArray();
    private static void Apply(EditorSession s)=>Ok(s.ApplyPreview(s.Snapshot.Preview!.Id));
    private static void Same(EditorSession s,EditorSnapshot before)=>Check(s.Snapshot==before,"Radial changed accepted/prior preview state.");
    private static void Near(Vec3 a,Vec3 b)=>Check(Math.Abs(a.X-b.X)<.001&&Math.Abs(a.Y-b.Y)<.001&&Math.Abs(a.Z-b.Z)<.001,$"Expected {b},got {a}.");
    private static void Ok(OperationResult result)=>Check(result.Succeeded,result.ToString());
    private static void Check(bool value,string message){if(!value)throw new Exception(message);}
    private sealed class Progress(Action<OperationProgress> action):IProgress<OperationProgress>{public void Report(OperationProgress p)=>action(p);}
    private static string Hash(string path)=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path)));
}
